create table "public"."course_modules" (
  "id"         bigint                   generated by default as identity not null,
  "course_id"  bigint                   not null,
  "title"      text                     not null,
  "position"   integer                  not null default 0,
  "created_at" timestamp with time zone not null default now(),
  constraint "course_modules_pkey" primary key (id),
  constraint "course_modules_course_id_fkey" foreign key (course_id) references public.learning_courses(id) on delete cascade
);

alter table "public"."course_modules"
  enable row level security;

create unique index course_modules_course_position_key on public.course_modules using btree (course_id, "position");

create unique index course_modules_id_course_id_key on public.course_modules using btree (id, course_id);

create policy "Published course modules are public" on "public"."course_modules"
  for select
  to "anon", "authenticated"
  using ((exists ( select 1
   from public.learning_courses course
  where ((course.id = course_modules.course_id) AND (course.status = 'published'::text) AND (not public.is_paystack_test_fixture_course(course.id))))));

grant select on table "public"."course_modules" to "anon", "authenticated";

grant delete, insert, maintain, references, select, trigger, truncate, update on table "public"."course_modules" to "postgres", "service_role";
